# Fix accidental space in Pune token
_GRIDS["pune"] = _GRIDS["pune"].replace("; holkar Bridge", ";Holkar Bridge")

_GRIDS["custom"] = _GRIDS["bengaluru"]


def _parse_city(raw: str) -> list[list[dict[str, Any]]]:
    rows: list[list[dict[str, Any]]] = []
    for line in raw.strip().splitlines():
        line = line.strip()
        if not line:
            continue
        cells: list[dict[str, Any]] = []
        for token in line.split(";"):
            parts = token.split("|")
            if len(parts) != 4:
                raise ValueError(f"Bad place token: {token!r}")
            name, land, elev, pop = parts
            cells.append(
                {
                    "name": name.strip(),
                    "land": land.strip(),
                    "elev": float(elev),
                    "pop": int(pop),
                }
            )
        if len(cells) != 12:
            raise ValueError(f"Expected 12 cells, got {len(cells)} in {cells[0]['name'] if cells else '?'}")
        rows.append(cells)
    if len(rows) != 12:
        raise ValueError(f"Expected 12 rows, got {len(rows)}")
    return rows


_CACHE: dict[str, list[list[dict[str, Any]]]] = {}


def place_at(city_id: str, row: int, col: int) -> dict[str, Any]:
    cid = city_id if city_id in _GRIDS else "bengaluru"
    if cid not in _CACHE:
        _CACHE[cid] = _parse_city(_GRIDS[cid])
    return _CACHE[cid][row][col]


def city_bounds(city_id: str) -> dict[str, float]:
    return BOUNDS.get(city_id, BOUNDS["bengaluru"])
